<div class="page-header"><div><span class="eyebrow">A SAFE SPACE FOR A LITTLE VULNERABILITY</span><h1>Keep this a good place to grow.</h1><p>Handle concerns carefully. Keep decisions specific, proportionate and recorded.</p></div><a class="text-link small muted" href="<?= e(route_url('/guidelines')) ?>">Community guidelines <?= icon('arrow-up-right',14) ?></a></div><div class="stack"><section class="card table-card"><div class="card-pad" style="padding-bottom:0"><div class="card-header"><h2>Reports that need a thoughtful look.</h2></div></div><?php if($reports): ?><?php foreach($reports as $r): ?><article class="card-pad" style="border-top:1px solid var(--border)"><div class="admin-review-meta"><div><h3 style="font-size:15px">Report #<?= (int)$r['id'] ?> · <?= e($r['reported']) ?></h3><p class="fine-print" style="margin-top:7px">Reported by <?= e($r['reporter']) ?> · <?= niceDate($r['created_at']) ?></p></div><?= badge($r['status']) ?></div><p class="review-response"><?= e($r['reason']) ?></p><?php if($r['status']==='open'): ?><form action="<?= e(route_url('/api/admin/moderate/report/' . ((int)$r['id']))) ?>" method="post" data-api><?= csrfField() ?><div class="field"><label for="resolve-<?= (int)$r['id'] ?>">Moderation outcome</label><textarea id="resolve-<?= (int)$r['id'] ?>" name="reason" minlength="10" maxlength="1000" required placeholder="Document the investigation and appropriate action…"></textarea></div><div class="page-actions"><button class="btn btn-secondary btn-small">Mark resolved & record outcome</button><a class="text-link small" href="<?= e(route_url('/admin/users/' . ((int)$r['reported_user_id']))) ?>">Review account access <?= icon('arrow-up-right',14) ?></a></div></form><?php else: ?><p class="fine-print">Resolution: <?= e($r['resolution']) ?></p><?php endif; ?></article><?php endforeach; ?><?php pagination($total); ?><?php else: emptyState('shield','A quiet moderation queue.','Community reports will appear here. Thank you for keeping the learning space constructive.');endif; ?></section><section class="card card-pad"><div class="card-header"><h2>Peer feedback moderation.</h2><p>Latest 20 submitted / hidden reviews</p></div><?php if($reviews): ?><?php foreach($reviews as $r): ?><details class="review-prompt"><summary style="font-size:12px;cursor:pointer"><?= e($r['snapshot_title']) ?> · <?= e($r['full_name']) ?> · <?= e($r['status']) ?></summary><?php foreach(\Learnow\Repositories\DB::all('SELECT pr.*,q.prompt FROM peer_review_responses pr JOIN peer_review_questions q ON q.id=pr.question_id WHERE pr.review_id=?',[$r['id']]) as $response): ?><div class="review-response"><strong><?= e($response['prompt']) ?> · <?= (int)$response['score'] ?></strong><br><?= e($response['feedback']) ?></div><?php endforeach; ?><?php if($r['status']!=='hidden'): ?><form action="<?= e(route_url('/api/admin/moderate/review/' . ((int)$r['id']))) ?>" method="post" data-api><?= csrfField() ?><div class="field"><label for="hide-<?= (int)$r['id'] ?>">Reason to hide this feedback</label><textarea id="hide-<?= (int)$r['id'] ?>" name="reason" minlength="10" maxlength="1000" required></textarea></div><button class="btn btn-danger btn-small">Hide feedback & record decision</button></form><?php endif; ?></details><?php endforeach; ?><?php else: ?><div class="mini-empty"><p>No submitted peer reviews to moderate.</p></div><?php endif; ?></section></div>
